//! Build-time generator for the official diagnostic code tables.
//!
//! Two TSVs, two tiers:
//!
//! - `data/syntax-codes.tsv` — the syntax tier, captured in the pinned
//!   syntax-codes capture and locked to the dart 3.13.1 oracle. Emits
//!   `syntax_codes_generated.rs` (per-code constants, the `SYNTAX_CODES`
//!   slice, the test payload, and the `message_template` face). Any
//!   malformed row fails the build with a `file:line` message.
//! - `data/analyzer-codes.tsv` — the full upstream analyzer registry
//!   (982 name rows generated by `tools/upstream-gen`'s
//!   `analyzer-codes-gen` from the pinned SDK tree's
//!   `pkg/analyzer/lib/src/diagnostic/diagnostic.g.dart`). Emits
//!   `analyzer_codes_generated.rs`: per-code constants for the
//!   non-syntax names, the merged full `OFFICIAL_CODES` table (the
//!   oracle-locked syntax rows override the registry rows for their 259
//!   names), the `ANALYZER_PUBLISHED_DOCS` name list behind
//!   `analyzer_docs::published`, and the `CODE_FAMILIES` class table
//!   behind `code::family`.
//!
//! Both emitted files are pure functions of their TSVs, so builds are
//! reproducible byte-for-byte; the cross-tier gate below fails the build
//! if any syntax-tier name disappears from the analyzer table.
//!
//! The syntax tier is also pinned against the oracle registry snapshot
//! (`data/oracle-syntax-registry-3.13.1.txt`): every `ParserErrorCode` /
//! `ScannerErrorCode` code the pinned 3.13.1 oracle can emit must exist in the
//! TSV unless it is an exempted measured-dead code — a missing name fails the
//! build, so the gate's acceptance set can never silently shrink below the
//! oracle's emit domain.

use rustc_hash::FxHashSet;
use std::env;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;

/// One validated TSV row (the 6 columns of `data/syntax-codes.tsv`).
struct Row {
    line: usize,
    name: String,
    machine: String,
    sev: String,
    source: String,
    message: String,
    has_published_docs: bool,
}

/// One validated row of `data/analyzer-codes.tsv` (7 or 8 columns: the
/// correction column is absent when upstream has none). The line column is
/// validated at parse time and not carried onward; the `class` column maps
/// to its [`CodeFamily`] variant (see `analyzer_family_of`).
struct AnalyzerRow {
    name: String,
    machine: String,
    dtype: String,
    family: &'static str,
    has_published_docs: bool,
    problem: String,
    correction: Option<String>,
}

fn main() {
    let manifest_dir_var = env::var("CARGO_MANIFEST_DIR").expect("cargo sets CARGO_MANIFEST_DIR");
    let manifest_dir = Path::new(&manifest_dir_var);
    let tsv_path = manifest_dir.join("data/syntax-codes.tsv");
    println!("cargo:rerun-if-changed=data/syntax-codes.tsv");

    let raw = fs::read_to_string(&tsv_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", tsv_path.display()));

    let mut rows = Vec::new();
    for (no, line) in raw.lines().enumerate() {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        assert!(
            fields.len() == 6,
            "data/syntax-codes.tsv:{}: expected 6 tab-separated columns, got {} \
             (the message column must not contain tabs)",
            no + 1,
            fields.len()
        );
        let has_published_docs = match fields[5] {
            "true" => true,
            "false" => false,
            other => panic!(
                "data/syntax-codes.tsv:{}: hasPublishedDocs must be true or false, got {other:?}",
                no + 1
            ),
        };
        rows.push(Row {
            line: no + 1,
            name: fields[0].to_owned(),
            machine: fields[1].to_owned(),
            sev: fields[2].to_owned(),
            source: fields[3].to_owned(),
            message: fields[4].to_owned(),
            has_published_docs,
        });
    }
    validate(&rows);
    pin_to_oracle_registry(manifest_dir, &rows);

    let analyzer = parse_analyzer_tsv(manifest_dir);
    cross_check_tiers(&rows, &analyzer);
    emit(&rows);
    emit_analyzer(&rows, &analyzer);
}

/// Parses and validates `data/analyzer-codes.tsv` (the generator-emitted
/// upstream registry table). Any malformed row fails the build with
/// `file:line`; the message columns carry the generator's TSV escaping
/// (`\\`, `\t`, `\n`, `\r`), unescaped here.
fn parse_analyzer_tsv(manifest_dir: &Path) -> Vec<AnalyzerRow> {
    let tsv_path = manifest_dir.join("data/analyzer-codes.tsv");
    println!("cargo:rerun-if-changed=data/analyzer-codes.tsv");
    let raw = fs::read_to_string(&tsv_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", tsv_path.display()));

    let mut rows: Vec<AnalyzerRow> = Vec::new();
    for (no, line) in raw.lines().enumerate() {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = line.split('\t').collect();
        let line = no + 1;
        assert!(
            matches!(fields.len(), 7 | 8),
            "data/analyzer-codes.tsv:{line}: expected 7 or 8 tab-separated columns, got {}",
            fields.len()
        );
        let [class, name, machine, dtype, sev, published, problem] =
            fields[..7].try_into().expect("length checked above");
        for (col, value) in [
            ("class", class),
            ("name", name),
            ("MACHINE", machine),
            ("TYPE", dtype),
            ("SEV", sev),
        ] {
            assert!(
                !value.is_empty(),
                "data/analyzer-codes.tsv:{line}: empty {col}"
            );
            assert!(
                value == value.trim(),
                "data/analyzer-codes.tsv:{line}: {col} {value:?} has leading or trailing whitespace"
            );
        }
        assert!(
            name.chars().enumerate().all(|(i, c)| c.is_ascii_lowercase()
                || c.is_ascii_digit() && i > 0
                || c == '_' && i > 0),
            "data/analyzer-codes.tsv:{line}: name {name:?} is not lowercase snake_case"
        );
        assert!(
            machine == name.to_uppercase(),
            "data/analyzer-codes.tsv:{line}: MACHINE {machine:?} is not the uppercase of {name:?}"
        );
        assert!(
            analyzer_dtype_of(dtype).is_some(),
            "data/analyzer-codes.tsv:{line}: TYPE {dtype:?} has no DiagnosticType variant — \
             a new upstream type must be mapped deliberately"
        );
        let family = analyzer_family_of(class).unwrap_or_else(|| {
            panic!(
                "data/analyzer-codes.tsv:{line}: class {class:?} has no CodeFamily variant — \
                 a new upstream registry class must be mapped deliberately"
            )
        });
        assert_eq!(
            sev,
            analyzer_severity(dtype),
            "data/analyzer-codes.tsv:{line}: SEV {sev:?} disagrees with the upstream \
             DiagnosticType constant for {dtype:?}"
        );
        let has_published_docs = match published {
            "true" => true,
            "false" => false,
            other => panic!(
                "data/analyzer-codes.tsv:{line}: hasPublishedDocs must be true or false, got {other:?}"
            ),
        };
        let problem = tsv_unescape(problem, line);
        let correction = fields.get(7).map(|value| tsv_unescape(value, line));
        // Rows are name-sorted (the generator's order): enforce strictly
        // increasing names — this catches duplicates and reordering alike,
        // and keeps ANALYZER_PUBLISHED_DOCS sorted for binary search.
        if let Some(prev) = rows.last() {
            assert!(
                prev.name.as_str() < name,
                "data/analyzer-codes.tsv:{line}: name {name:?} does not sort after {:?}",
                prev.name
            );
        }
        rows.push(AnalyzerRow {
            name: name.to_owned(),
            machine: machine.to_owned(),
            dtype: dtype.to_owned(),
            family,
            has_published_docs,
            problem,
            correction,
        });
    }
    assert!(
        !rows.is_empty(),
        "data/analyzer-codes.tsv carries no data rows — regenerate with \
         cargo run -p upstream-gen --bin analyzer-codes-gen -- --sdk-src <dart-sdk-tree>"
    );
    rows
}

/// Undoes the generator's message-column escaping.
fn tsv_unescape(value: &str, line: usize) -> String {
    let mut out = String::with_capacity(value.len());
    let mut chars = value.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('t') => out.push('\t'),
            Some('n') => out.push('\n'),
            Some('r') => out.push('\r'),
            Some('\\') => out.push('\\'),
            other => panic!(
                "data/analyzer-codes.tsv:{line}: unknown escape sequence \\{other:?} \
                 in a message column"
            ),
        }
    }
    out
}

/// The [`crate::model::DiagnosticType`] variant for an upstream
/// `DiagnosticType` spelling.
fn analyzer_dtype_of(dtype: &str) -> Option<&'static str> {
    match dtype {
        "SYNTACTIC_ERROR" => Some("SyntacticError"),
        "COMPILE_TIME_ERROR" => Some("CompileTimeError"),
        "STATIC_WARNING" => Some("StaticWarning"),
        "HINT" => Some("Hint"),
        "TODO" => Some("Todo"),
        // Lint codes never enter this registry (they live in pkg/linter);
        // the mapping exists so a future upstream change maps instead of
        // silently failing.
        "LINT" => Some("Lint"),
        _ => None,
    }
}

/// The [`crate::code::CodeFamily`] variant for an upstream registry class
/// spelling (the TSV `class` column). `_fe_analyzer_shared` is the shared
/// front-end package's parser registry — its rows report exactly like the
/// `ParserErrorCode` family, so the variant carries the package spelling.
/// An unknown class fails the build: a new upstream registry must be
/// mapped deliberately, never folded into a silent variant.
fn analyzer_family_of(class: &str) -> Option<&'static str> {
    match class {
        "CompileTimeErrorCode" => Some("CompileTimeErrorCode"),
        "StaticWarningCode" => Some("StaticWarningCode"),
        "WarningCode" => Some("WarningCode"),
        "HintCode" => Some("HintCode"),
        "TodoCode" => Some("TodoCode"),
        "ParserErrorCode" => Some("ParserErrorCode"),
        "ScannerErrorCode" => Some("ScannerErrorCode"),
        "_fe_analyzer_shared" => Some("FeAnalyzerShared"),
        "PubspecWarningCode" => Some("PubspecWarningCode"),
        "ManifestWarningCode" => Some("ManifestWarningCode"),
        "AnalysisOptionsErrorCode" => Some("AnalysisOptionsErrorCode"),
        "AnalysisOptionsWarningCode" => Some("AnalysisOptionsWarningCode"),
        "FfiCode" => Some("FfiCode"),
        "JsInteropCode" => Some("JsInteropCode"),
        _ => None,
    }
}

/// The severity the upstream `DiagnosticType` constants carry (the same
/// mapping as `tools/upstream-gen`'s `severity_of`, itself transcribed
/// from the upstream `DiagnosticType` declarations): ERROR for
/// `SYNTACTIC_ERROR`/`COMPILE_TIME_ERROR`, WARNING for `STATIC_WARNING`,
/// INFO for `HINT`/`TODO`/`LINT`.
fn analyzer_severity(dtype: &str) -> &'static str {
    match analyzer_dtype_of(dtype) {
        Some("StaticWarning") => "WARNING",
        Some("Hint" | "Todo" | "Lint") => "INFO",
        _ => "ERROR",
    }
}

/// Cross-tier gate: every syntax-tier name must exist in the analyzer
/// registry table. The registry is the full official set; a syntax name
/// dropping out means the tracked analyzer-codes.tsv is stale (or the
/// upstream pin moved under it) — either way the merged `OFFICIAL_CODES`
/// table must not ship with a silent hole.
fn cross_check_tiers(syntax: &[Row], analyzer: &[AnalyzerRow]) {
    let analyzer_names: FxHashSet<&str> = analyzer.iter().map(|row| row.name.as_str()).collect();
    for row in syntax {
        assert!(
            analyzer_names.contains(row.name.as_str()),
            "data/analyzer-codes.tsv: syntax-tier code `{}` is missing from the analyzer \
             registry table — regenerate with cargo run -p upstream-gen --bin \
             analyzer-codes-gen -- --sdk-src <dart-sdk-tree>",
            row.name
        );
    }
}

/// Structural validation over the whole table; panics with the offending
/// data line on the first violation.
fn validate(rows: &[Row]) {
    let mut names: Vec<&str> = Vec::with_capacity(rows.len());
    for row in rows {
        let Row {
            line,
            name,
            machine,
            sev,
            source,
            message,
            ..
        } = row;
        for (col, value) in [("name", name), ("MACHINE", machine), ("message", message)] {
            assert!(
                !value.is_empty(),
                "data/syntax-codes.tsv:{line}: empty {col}"
            );
        }
        // Stray whitespace in any column is a byte-diff class error (a
        // trailing space in `message` would flow into `message_template` and
        // then into `problemMessage` output); reject it at build time.
        for (col, value) in [
            ("name", name),
            ("MACHINE", machine),
            ("SEV", sev),
            ("SOURCE", source),
            ("message", message),
        ] {
            assert!(
                value == value.trim(),
                "data/syntax-codes.tsv:{line}: {col} {value:?} has leading or trailing whitespace"
            );
        }
        assert!(
            sev == "ERROR" || sev == "WARNING",
            "data/syntax-codes.tsv:{line}: SEV must be ERROR or WARNING, got {sev:?}"
        );
        // `source` = oracle registry class + same-name const count; the first
        // char picks the machine TYPE in `dtype_of`. An unknown class must be
        // a build error, not a silent SYNTACTIC_ERROR fallback.
        assert!(
            matches!(source.as_bytes().first(), Some(b'P' | b'S' | b'W' | b'C')),
            "data/syntax-codes.tsv:{line}: source {source:?} must start with P, S, W or C"
        );
        assert!(
            machine == &name.to_uppercase(),
            "data/syntax-codes.tsv:{line}: MACHINE {machine:?} is not the uppercase of {name:?}"
        );
        for (index, _) in placeholders(message) {
            assert!(
                index <= 1,
                "data/syntax-codes.tsv:{line}: placeholder index {index} exceeds the \
                 measured upper bound (syntax templates take at most 2 arguments)"
            );
        }
        names.push(name);
    }
    let mut sorted = names.clone();
    sorted.sort_unstable();
    let dupes: Vec<&str> = sorted
        .windows(2)
        .filter(|w| w[0] == w[1])
        .map(|w| w[0])
        .collect();
    assert!(
        dupes.is_empty(),
        "data/syntax-codes.tsv: duplicate code names {dupes:?}"
    );
}

/// Coverage pin against the pinned oracle registry: every `ParserErrorCode` /
/// `ScannerErrorCode` code of analyzer-8.4.1 + _fe_analyzer_shared-91.0.0
/// (`data/oracle-syntax-registry-3.13.1.txt`) must exist in the TSV unless it
/// is an exempted measured-dead code. A missing name means the gate's
/// acceptance set would silently drop every oracle diagnostic carrying it; a
/// stale exemption means the snapshot was refreshed without re-deriving the
/// prune rationale. Build-time on purpose: `cargo check` re-runs the pin.
fn pin_to_oracle_registry(manifest_dir: &Path, rows: &[Row]) {
    /// removedIn codes pruned from the TSV as measured-dead (TSV header,
    /// the pinned syntax-codes capture): present in the pinned registry,
    /// never emitted by the pinned oracle, so they must not gate the pin.
    const EXEMPTED_REGISTRY_CODES: [&str; 7] = [
        "invalid_operator_for_super",
        "missing_terminator_for_parameter_group",
        "multiple_variables_in_for_each",
        "non_user_definable_operator",
        "unable_get_content",
        "unexpected_terminator_for_parameter_group",
        "wrong_terminator_for_parameter_group",
    ];

    let snapshot_path = manifest_dir.join("data/oracle-syntax-registry-3.13.1.txt");
    println!("cargo:rerun-if-changed=data/oracle-syntax-registry-3.13.1.txt");
    let snapshot = fs::read_to_string(&snapshot_path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", snapshot_path.display()));

    let tsv_names: FxHashSet<&str> = rows.iter().map(|row| row.name.as_str()).collect();
    let mut exempted: FxHashSet<&str> = EXEMPTED_REGISTRY_CODES.into_iter().collect();
    for (no, line) in snapshot.lines().enumerate() {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        assert!(
            line.chars()
                .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_'),
            "data/oracle-syntax-registry-3.13.1.txt:{}: expected a lowercase snake_case \
             code name, got {line:?}",
            no + 1
        );
        let gated = exempted.remove(line) || tsv_names.contains(line);
        assert!(
            gated,
            "data/oracle-syntax-registry-3.13.1.txt:{}: oracle registry code `{line}` \
             is missing from data/syntax-codes.tsv — the gate's acceptance set would \
             silently drop every oracle diagnostic carrying it; add the row (with its \
             source class and captured template) or extend EXEMPTED_REGISTRY_CODES \
             with a recorded rationale",
            no + 1
        );
    }
    if !exempted.is_empty() {
        let mut stale: Vec<&str> = exempted.into_iter().collect();
        stale.sort_unstable();
        panic!(
            "data/oracle-syntax-registry-3.13.1.txt: EXEMPTED_REGISTRY_CODES entries no \
             longer present in the registry snapshot: {stale:?} — the snapshot was \
             refreshed; re-derive the exemption list (delete the retired names or \
             re-record the prune rationale)"
        );
    }
}

/// Indices of `{N}` placeholders in a template, as `(index, byte offset)`.
///
/// A placeholder is `{`, a non-empty ASCII digit run, then `}` — scanned in
/// a single pass, so multi-digit indices (`{10}`) are validated too (a
/// 3-byte window is blind to them). Literal braces (`"{'"`, `"{}"`) never
/// match because a placeholder requires digits inside.
fn placeholders(message: &str) -> Vec<(u32, usize)> {
    let bytes = message.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'{' {
            let digits = bytes[i + 1..]
                .iter()
                .take_while(|&&b| b.is_ascii_digit())
                .count();
            if digits > 0 && bytes.get(i + 1 + digits) == Some(&b'}') {
                let index: u32 = message[i + 1..i + 1 + digits].parse().unwrap_or_else(|e| {
                    panic!("placeholder index at byte {i} does not fit u32: {e}")
                });
                out.push((index, i));
                i += digits + 2;
                continue;
            }
        }
        i += 1;
    }
    out
}

/// The [`crate::model::DiagnosticType`] variant name for a row, from its
/// oracle registry class (TSV `source` column).
///
/// - `C*` sources: `CompileTimeErrorCode` consts (the ERROR-level
///   language-version rows) — class type `COMPILE_TIME_ERROR`
///   (analyzer-8.4.1 codes.g.dart: `illegalLanguageVersionOverride`
///   `CompileTimeErrorTemplate`, `inconsistentLanguageVersionOverride`
///   `CompileTimeErrorWithoutArguments`).
/// - `W*` sources: `WarningCode` consts (`invalid_language_version_override`)
///   — class type `STATIC_WARNING`.
/// - Everything else: parser/scanner class type `SYNTACTIC_ERROR`.
///
/// Per-row severity overrides the class severity; the emitted
/// SEVERITY comes from the diagnostics, the TYPE from this mapping.
/// `COMPILE_TIME_ERROR` routing of pseudoSharedCode parser errors
/// is an emit-site decision per parse route and is not a property of the
/// table.
fn dtype_of(source: &str) -> &'static str {
    if source.starts_with('C') {
        "CompileTimeError"
    } else if source.starts_with('W') {
        "StaticWarning"
    } else {
        "SyntacticError"
    }
}

fn emit(rows: &[Row]) {
    let out_dir_var = env::var("OUT_DIR").expect("cargo sets OUT_DIR");
    let out_dir = Path::new(&out_dir_var);
    let mut out = String::new();
    out.push_str("// @generated by build.rs from data/syntax-codes.tsv; do not edit.\n");
    out.push_str("// Source of truth: data/syntax-codes.tsv\n");
    out.push_str("// (dart 3.13.1 oracle lock, captured 2026-10-08).\n");
    out.push_str("// Regenerate: cargo build -p dartq-diagnostics.\n");
    out.push_str("use crate::code::CodeInfo;\n");
    out.push_str("use crate::model::DiagnosticType;\n\n");

    // One constant per code; the MACHINE column is already the SCREAMING_SNAKE
    // Rust identifier (validated above).
    for row in rows {
        let doc = format!("`{}` — {}", row.name, doc_esc(&row.message));
        writeln!(out, "#[doc = {}]", rust_str(&doc)).unwrap();
        writeln!(
            out,
            "pub const {}: CodeInfo = CodeInfo::new(\n    {},\n    {},\n    DiagnosticType::{},\n    {},\n);\n",
            row.machine,
            rust_str(&row.name),
            rust_str(&row.machine),
            dtype_of(&row.source),
            row.has_published_docs,
        )
        .unwrap();
    }

    writeln!(
        out,
        "/// All {} syntax-tier codes (255 registry-gated codes plus 4 supplemental\n/// rows), in table order. The full official set is `OFFICIAL_CODES` in\n/// `analyzer_codes_generated.rs` (this slice is its oracle-locked prefix).",
        rows.len()
    )
    .unwrap();
    out.push_str("pub static SYNTAX_CODES: &[CodeInfo] = &[\n");
    for row in rows {
        writeln!(
            out,
            "    CodeInfo::new({}, {}, DiagnosticType::{}, {}),",
            rust_str(&row.name),
            rust_str(&row.machine),
            dtype_of(&row.source),
            row.has_published_docs,
        )
        .unwrap();
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// `(name, oracle SEV, message template, hasPublishedDocs)` rows in table order;\n",
    );
    out.push_str("/// backs the consistency tests (against the live [`message_template`] face\n");
    out.push_str("/// and the emit-path pins). Test-only payload: emitters render through the\n");
    out.push_str("/// generated match, so the static is compiled only into test builds.\n");
    out.push_str("#[cfg(test)]\n");
    out.push_str("pub static OFFICIAL_CODE_DATA: &[(&str, &str, &str, bool)] = &[\n");
    for row in rows {
        writeln!(
            out,
            "    ({}, {}, {}, {}),",
            rust_str(&row.name),
            rust_str(&row.sev),
            rust_str(&row.message),
            row.has_published_docs,
        )
        .unwrap();
    }
    out.push_str("];\n");

    // The emission-path template face: a match over the literal rows, so a
    // lookup is a string-match dispatch (no table scan, no map build) and a
    // name absent from the table falls to the explicit `None` arm — callers
    // that require a row fail loudly on it instead of rendering a default.
    out.push_str("\n/// Message template of an official code, by exact name (`{0}`/`{1}` are\n");
    out.push_str("/// substitution placeholders). The emission-path single source: emitters\n");
    out.push_str("/// whose code rows are byte-pinned against this table render from it\n");
    out.push_str("/// instead of carrying local literals. Official codes only — dartq-own\n");
    out.push_str("/// codes carry their messages at the emit site.\n");
    out.push_str("#[must_use]\n");
    out.push_str("pub fn message_template(name: &str) -> Option<&'static str> {\n");
    out.push_str("    match name {\n");
    for row in rows {
        writeln!(
            out,
            "        {} => Some({}),",
            rust_str(&row.name),
            rust_str(&row.message)
        )
        .unwrap();
    }
    out.push_str("        _ => None,\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    fs::write(out_dir.join("syntax_codes_generated.rs"), out).expect("write generated code table");
}

/// Emits `analyzer_codes_generated.rs`: the per-code constants for the
/// non-syntax registry names, the merged full `OFFICIAL_CODES` table
/// (syntax tier first — byte-identical to the pre-registry table — then
/// the remaining analyzer rows in name-sorted table order), the
/// `ANALYZER_PUBLISHED_DOCS` list behind `analyzer_docs::published`, and
/// the `CODE_FAMILIES` class table behind `code::family`.
fn emit_analyzer(syntax: &[Row], analyzer: &[AnalyzerRow]) {
    let out_dir_var = env::var("OUT_DIR").expect("cargo sets OUT_DIR");
    let out_dir = Path::new(&out_dir_var);
    let syntax_names: FxHashSet<&str> = syntax.iter().map(|row| row.name.as_str()).collect();

    let mut out = String::with_capacity(analyzer.len() * 160);
    out.push_str("// @generated by build.rs from data/analyzer-codes.tsv; do not edit.\n");
    out.push_str("// Source of truth: data/analyzer-codes.tsv (generated by\n");
    out.push_str("// tools/upstream-gen's analyzer-codes-gen from the pinned SDK tree).\n");
    out.push_str("use crate::code::CodeFamily;\n");
    out.push_str("use crate::code::CodeInfo;\n");
    out.push_str("use crate::model::DiagnosticType;\n\n");

    // Per-code constants for the registry names the syntax tier does not
    // already cover (the syntax tier's constants are generated from its
    // own table and stay byte-stable for parser/scanner consumers).
    for row in analyzer {
        if syntax_names.contains(row.name.as_str()) {
            continue;
        }
        let doc = match &row.correction {
            Some(correction) => {
                format!(
                    "`{}` — {} (correction: {})",
                    row.name, row.problem, correction
                )
            }
            None => format!("`{}` — {}", row.name, row.problem),
        };
        writeln!(out, "#[doc = {}]", rust_str(&doc_esc(&doc))).unwrap();
        writeln!(
            out,
            "pub const {}: CodeInfo = CodeInfo::new(\n    {},\n    {},\n    DiagnosticType::{},\n    {},\n);\n",
            row.machine,
            rust_str(&row.name),
            rust_str(&row.machine),
            analyzer_dtype_of(&row.dtype).expect("validated at parse time"),
            row.has_published_docs,
        )
        .unwrap();
    }

    writeln!(
        out,
        "/// All {} official codes: the {} oracle-locked syntax-tier rows first\n/// (byte-identical to `SYNTAX_CODES`, the pre-registry table), then the\n/// remaining upstream registry rows in name-sorted table order. For the\n/// syntax tier's names the pinned 3.13.1 capture overrides the registry\n/// (3.15 recast `field_initializer_outside_constructor` to\n/// COMPILE_TIME_ERROR and moved two templates; the acceptance set stays\n/// oracle-locked).",
        syntax.len() + analyzer.len() - syntax_names.len(),
        syntax.len(),
    )
    .unwrap();
    out.push_str("pub static OFFICIAL_CODES: &[CodeInfo] = &[\n");
    for row in syntax {
        writeln!(
            out,
            "    CodeInfo::new({}, {}, DiagnosticType::{}, {}),",
            rust_str(&row.name),
            rust_str(&row.machine),
            dtype_of(&row.source),
            row.has_published_docs,
        )
        .unwrap();
    }
    for row in analyzer {
        if syntax_names.contains(row.name.as_str()) {
            continue;
        }
        writeln!(
            out,
            "    CodeInfo::new({}, {}, DiagnosticType::{}, {}),",
            rust_str(&row.name),
            rust_str(&row.machine),
            analyzer_dtype_of(&row.dtype).expect("validated at parse time"),
            row.has_published_docs,
        )
        .unwrap();
    }
    out.push_str("];\n\n");

    out.push_str("/// The registry names whose upstream entry is `hasPublishedDocs: true`\n");
    out.push_str("/// (name-sorted; binary-searchable) — the table behind\n");
    out.push_str("/// `analyzer_docs::published`.\n");
    out.push_str("pub static ANALYZER_PUBLISHED_DOCS: &[&str] = &[\n");
    for row in analyzer {
        if row.has_published_docs {
            writeln!(out, "    {},", rust_str(&row.name)).unwrap();
        }
    }
    out.push_str("];\n");

    // The upstream registry class of every official code — name-sorted
    // (the parse's strictly-increasing order), binary-searchable by
    // `code::family`. Same TSV parse as `OFFICIAL_CODES`, so the name
    // sets are identical by construction.
    out.push_str("\n/// The upstream registry class of each analyzer registry code (the TSV\n");
    out.push_str("/// `class` column), in the table's name-sorted order — the lookup data\n");
    out.push_str("/// behind `code::family`.\n");
    out.push_str("pub static CODE_FAMILIES: &[(&str, CodeFamily)] = &[\n");
    for row in analyzer {
        writeln!(
            out,
            "    ({}, CodeFamily::{}),",
            rust_str(&row.name),
            row.family
        )
        .unwrap();
    }
    out.push_str("];\n");

    fs::write(out_dir.join("analyzer_codes_generated.rs"), out)
        .expect("write generated analyzer table");
}

/// Escapes rustdoc link brackets so table prose like `'[0]'` renders
/// literally instead of parsing as a broken intra-doc link.
fn doc_esc(s: &str) -> String {
    s.replace('[', "\\[").replace(']', "\\]")
}

/// Renders `s` as a Rust string literal (escapes `\`, `"`, and the
/// whitespace escapes a message column may carry after unescaping).
fn rust_str(s: &str) -> String {
    let mut quoted = String::with_capacity(s.len() + 2);
    quoted.push('"');
    for c in s.chars() {
        match c {
            '"' => quoted.push_str("\\\""),
            '\\' => quoted.push_str("\\\\"),
            '\n' => quoted.push_str("\\n"),
            '\t' => quoted.push_str("\\t"),
            '\r' => quoted.push_str("\\r"),
            c => quoted.push(c),
        }
    }
    quoted.push('"');
    quoted
}
